def render_html_toc(renderer: 'BaseRenderer', title: str, collapse: bool=
    False, **attrs: Any) ->str:
    toc = attrs.get('toc', [])
    if not toc:
        return ''

    ul = render_toc_ul(toc)

    if collapse:
        if title:
            summary = '<summary>' + title + '</summary>\n'
        else:
            summary = '<summary>Table of Contents</summary>\n'
        return '<details open>\n' + summary + ul + '</details>\n'

    if title:
        return '<section class="toc">\n<h2>' + title + '</h2>\n' + ul + '</section>\n'

    return '<section class="toc">\n' + ul + '</section>\n'

